mapper.select:
SELECT  
ORDER BY s.created_at DESC, s.id DESC
LIMIT #{query.pageSize} OFFSET #{query.offset}


SELECT s.id,f.factory_name,EXISTS(SELECT 1 FROM prop_sku_audit a WHERE a.sku_id=s.id AND a.action_type='create' AND a.audit_status='approved') formed,st.id stock_id,st.total_quantity,GREATEST(CAST(st.rentable_base_quantity AS DECIMAL(30,0))-COALESCE(r.occupied,0),0) available_quantity,COALESCE(n.total,0) sn_total,COALESCE(n.available,0) sn_available FROM prop_sku s JOIN factory_profile f ON f.id=s.factory_id LEFT JOIN prop_sku_stock st ON st.sku_id=s.id LEFT JOIN (SELECT sn.sku_id,SUM(sn.instance_status IN ('idle','locked','renting','repairing')) total,SUM(sn.instance_status='idle' AND NOT EXISTS(SELECT 1 FROM inventory_reservation ir WHERE ir.sn_id=sn.id AND ir.reservation_status IN ('held','paid_locked','renting','overdue_holding','disputed_holding') AND ir.occupy_start_date<=#{today} AND >=#{today}) AND NOT EXISTS(SELECT 1 FROM prop_sn_adjustment_item i JOIN prop_sn_adjustment_audit a ON a.id=i.adjustment_audit_id WHERE i.sn_id=sn.id AND a.audit_status='pending')) available FROM prop_sn_instance sn WHERE sn.sku_id IN 
#{value}
 GROUP BY sn.sku_id) n ON n.sku_id=s.id LEFT JOIN (SELECT sku_id,SUM(CAST(quantity AS DECIMAL(30,0))) occupied FROM inventory_reservation WHERE sn_id IS NULL AND reservation_status IN ('held','paid_locked','renting','overdue_holding','disputed_holding') AND occupy_start_date<=#{today} AND >=#{today} AND sku_id IN #{value} GROUP BY sku_id) r ON r.sku_id=s.id WHERE s.id IN 
#{value}

