 AND EXISTS(SELECT 1 FROM prop_sku_style st WHERE st.sku_id=s.id AND st.style_code IN 
#{style}
)

mapper.select:
SELECT COUNT(*) FROM prop_sku s WHERE 1=1
 AND s.factory_id=#{ownedQueryDTO.ownerFactory}

 AND s.factory_id=#{ownedQueryDTO.factoryId}
 AND s.sku_status=#{ownedQueryDTO.skuStatus}

   AND (LOCATE(#{ownedQueryDTO.keyword},s.prop_name)>0 OR LOCATE(#{ownedQueryDTO.keyword},CONVERT(s.sku_code USING utf8mb4) COLLATE utf8mb4_bin)>0
   OR EXISTS(SELECT 1 FROM prop_sn_instance sn WHERE sn.sku_id=s.id AND LOCATE(#{ownedQueryDTO.keyword},CONVERT(sn.sn_code USING utf8mb4) COLLATE utf8mb4_bin)>0)
  )

 AND EXISTS(SELECT 1 FROM factory_profile f WHERE f.id=s.factory_id AND LOCATE(#{ownedQueryDTO.factoryKeyword},f.factory_name)>0)

   AND 
  NOT
   EXISTS(SELECT 1 FROM prop_sku_audit a WHERE a.sku_id=s.id AND a.audit_status='pending')

SELECT s.id, s.asset_type, s.created_at, s.daily_rent_price_fen, s.deposit_amount_fen, s.factory_id, s.fill_status, s.fire_resistant_code, s.height_cm, s.length_cm, s.material_desc, s.packaging_factor_bps, s.prop_name, s.remark, s.size_desc, s.sku_code, s.sku_status, s.transport_suggestion, s.type_code, s.updated_at, s.version, s.weight_kg, s.width_cm FROM prop_sku s WHERE 1=1
 AND s.factory_id=#{ownedQueryDTO.ownerFactory}

 AND s.factory_id=#{ownedQueryDTO.factoryId}
 AND s.sku_status=#{ownedQueryDTO.skuStatus}

   AND (LOCATE(#{ownedQueryDTO.keyword},s.prop_name)>0 OR LOCATE(#{ownedQueryDTO.keyword},CONVERT(s.sku_code USING utf8mb4) COLLATE utf8mb4_bin)>0
   OR EXISTS(SELECT 1 FROM prop_sn_instance sn WHERE sn.sku_id=s.id AND LOCATE(#{ownedQueryDTO.keyword},CONVERT(sn.sn_code USING utf8mb4) COLLATE utf8mb4_bin)>0)
  )

 AND EXISTS(SELECT 1 FROM factory_profile f WHERE f.id=s.factory_id AND LOCATE(#{ownedQueryDTO.factoryKeyword},f.factory_name)>0)

   AND 
  NOT
   EXISTS(SELECT 1 FROM prop_sku_audit a WHERE a.sku_id=s.id AND a.audit_status='pending')

 ORDER BY s.created_at DESC,s.id DESC LIMIT #{ownedQueryDTO.limit} OFFSET #{ownedQueryDTO.offset}
